---
---@enum LOG
---@see Spring.Log
LOG = {
	DEBUG = 20,

	INFO = 30,

	---Engine default.
	NOTICE = 35,

	DEPRECATED = 37,

	WARNING = 40,

	ERROR = 50,

	FATAL = 60
}

---[<a href="https://github.com/beyond-all-reason/RecoilEngine/blob/master/rts/Lua/LuaUtils.cpp#L1436-L1446" target="_blank">source</a>]
---
---@alias LogLevel
---| integer
---| "debug"      # LOG.DEBUG
---| "info"       # LOG.INFO
---| "notice"     # LOG.NOTICE (engine default)
---| "warning"    # LOG.WARNING
---| "deprecated" # LOG.DEPRECATED
---| "error"      # LOG.ERROR
---| "fatal"      # LOG.FATAL

